export function formatPythonList(values) {
  return `[${values.join(', ')}]`;
}

export function formatPythonBoolean(value) {
  return value ? 'True' : 'False';
}

const PYTHON_INT_PATTERN = /^[+-]?\d(?:[\d_]*\d)?$|^[+-]?\d$/;

export class PythonIntValueError extends Error {
  constructor(token) {
    super(`invalid literal for int() with base 10: '${token}'`);
    this.name = 'ValueError';
    this.token = token;
  }
}

function isValidPythonIntegerToken(token) {
  if (!PYTHON_INT_PATTERN.test(token)) {
    return false;
  }

  return !token.includes('__') && !token.startsWith('_') && !token.endsWith('_');
}

export function parsePythonInteger(token) {
  const normalized = token.trim();

  if (!isValidPythonIntegerToken(normalized)) {
    throw new PythonIntValueError(token);
  }

  return Number(normalized.replaceAll('_', ''));
}

export function parseCommaSeparatedIntegers(text) {
  return text.split(',').map((token) => parsePythonInteger(token));
}

export function formatPythonIntTraceback(error) {
  return [
    'Traceback (most recent call last):',
    '  File "test10.py", line 18, in <module>',
    '  File "test10.py", line 10, in main',
    `${error.name}: ${error.message}`,
  ].join('\n');
}

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;
const LONG_HELP_OPTION = '--help';

function basename(path) {
  const normalized = String(path ?? '').replace(/\\/g, '/');
  const segments = normalized.split('/');
  return segments[segments.length - 1] || normalized;
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function help(programName) {
  return `${usage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B`;
}

function exitWithHelp(programName) {
  process.stdout.write(`${help(programName)}\n`);
  process.exit(0);
}

function exitWithParseError(programName, message) {
  process.stderr.write(`${usage(programName)}\n`);
  process.stderr.write(`${programName}: error: ${message}\n`);
  process.exit(2);
}

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function isOptionLikeToken(token) {
  return token.startsWith('-') && token !== '-' && !isNegativeNumberLike(token);
}

function isLongHelpPrefix(option) {
  return option.length >= 3 && LONG_HELP_OPTION.startsWith(option);
}

function isLongHelpToken(token) {
  return !token.includes('=') && isLongHelpPrefix(token);
}

function isLongHelpWithExplicitArgument(token) {
  const separatorIndex = token.indexOf('=');

  if (separatorIndex === -1) {
    return false;
  }

  return isLongHelpPrefix(token.slice(0, separatorIndex));
}

function isShortHelpToken(token) {
  return token.startsWith('-h') && !token.startsWith('--') && !token.startsWith('-h=');
}

function isShortHelpWithExplicitArgument(token) {
  return token.startsWith('-h=');
}

function readOptionValue(tokens, index, optionName, programName) {
  const nextToken = tokens[index + 1];

  if (nextToken === undefined || isOptionLikeToken(nextToken)) {
    exitWithParseError(programName, `argument ${optionName}: expected one argument`);
  }

  return nextToken;
}

export function parseTest10Args(argv = process.argv) {
  const programName = basename(argv[1] ?? 'test10.mjs');
  const tokens = argv.slice(2);
  const extras = [];
  let a;
  let b;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '--') {
      extras.push(...tokens.slice(index));
      break;
    }

    if (isShortHelpWithExplicitArgument(token) || isLongHelpWithExplicitArgument(token)) {
      const separatorIndex = token.indexOf('=');
      const explicitArgument = token.slice(separatorIndex + 1);
      exitWithParseError(
        programName,
        `argument -h/--help: ignored explicit argument '${explicitArgument}'`,
      );
    }

    if (isShortHelpToken(token) || isLongHelpToken(token)) {
      exitWithHelp(programName);
    }

    if (token === '--a') {
      a = readOptionValue(tokens, index, '--a', programName);
      index += 1;
      continue;
    }

    if (token === '--b') {
      b = readOptionValue(tokens, index, '--b', programName);
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      a = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      b = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (a === undefined) {
    missing.push('--a');
  }

  if (b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    exitWithParseError(
      programName,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    exitWithParseError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a, b };
}

export function getTest10Usage(programName = 'test10.mjs') {
  return usage(programName);
}

export function getTest10Help(programName = 'test10.mjs') {
  return help(programName);
}

