import { BECH32_CHECKSUM_LENGTH } from './constants.mjs';
import { bech32HrpExpand, bech32Polymod } from './polymod.mjs';

export function bech32CreateChecksum(humanReadablePart, data) {
  const values = [...bech32HrpExpand(humanReadablePart), ...data];
  const polymod = (bech32Polymod([
    ...values,
    ...new Array(BECH32_CHECKSUM_LENGTH).fill(0),
  ]) ^ 1) >>> 0;

  return Array.from({ length: BECH32_CHECKSUM_LENGTH }, (_, index) => {
    const shift = 5 * (BECH32_CHECKSUM_LENGTH - 1 - index);
    return (polymod >>> shift) & 31;
  });
}

export function bech32VerifyChecksum(humanReadablePart, data) {
  return bech32Polymod([...bech32HrpExpand(humanReadablePart), ...data]) === 1;
}

export {
  bech32CreateChecksum,
  bech32VerifyChecksum,
  bech32_create_checksum,
  bech32_verify_checksum,
} from './checksum.mjs';

export const BECH32_GENERATORS = [
  0x3b6a57b2,
  0x26508e6d,
  0x1ea119fa,
  0x3d4233dd,
  0x2a1462b3,
];

export const BECH32_CHECKSUM_LENGTH = 6;

export function expandHrp(hrp) {
  const highBits = [];
  const lowBits = [];

  for (const character of hrp) {
    const codePoint = character.codePointAt(0);
    highBits.push(codePoint >> 5);
    lowBits.push(codePoint & 31);
  }

  return [...highBits, 0, ...lowBits];
}

import { BECH32_GENERATORS } from './constants.mjs';

export function bech32HrpExpand(humanReadablePart) {
  const expanded = [];

  for (const character of humanReadablePart) {
    expanded.push(character.charCodeAt(0) >> 5);
  }

  expanded.push(0);

  for (const character of humanReadablePart) {
    expanded.push(character.charCodeAt(0) & 31);
  }

  return expanded;
}

export function bech32Polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >>> 25;
    checksum = (((checksum & 0x1ffffff) << 5) ^ value) >>> 0;

    for (let index = 0; index < BECH32_GENERATORS.length; index += 1) {
      if ((top >>> index) & 1) {
        checksum = (checksum ^ BECH32_GENERATORS[index]) >>> 0;
      }
    }
  }

  return checksum >>> 0;
}
